from target import merge_routes


def test_tenant_value_overrides_default():
    assert merge_routes({"timeout": 5}, {"timeout": 9}) == {"timeout": 9}


def test_nested_route_is_merged_not_replaced():
    result = merge_routes(
        {"route": {"host": "h", "timeout": 5}},
        {"route": {"timeout": 9}},
    )
    assert result == {"route": {"host": "h", "timeout": 9}}


def test_empty_tenant_section_keeps_default_route():
    assert merge_routes({"route": {"host": "h"}}, {"route": {}}) == {"route": {"host": "h"}}
